const TEXTS: Record<string, HymnText> = {
  "6": {"firstLine": "Christ, whose glory fills the skies", "credit": "Author: Charles Wesley, 1707-1788", "source": null, "stanzas": ["Christ, whose glory fills the skies,\nChrist, the true, the only Light,\nSun of Righteousness, arise!\nTriumph over shades of night;\nDayspring from on high, be near;\nDaystar, in my heart appear!", "Dark and cheerless is the morn\nunaccompanied by thee;\njoyless is the day’s return\ntill thy mercy’s beams I see,\nas they inward light impart,\nglad my eyes, and warm my heart.", "Visit then this soul of mine!\nPierce the gloom of sin and grief!\nFill me, radiancy divine;\nscatter all my unbelief;\nmore and more thyself display,\nshining to the perfect day."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/6"},
  "10": {"firstLine": "New every morning is the love", "credit": "Author: John Keble, 1792-1866", "source": null, "stanzas": ["New every morning is the love\nour wakening and uprising prove;\nthrough sleep and darkness safely brought,\nrestored to life and power and thought.", "New mercies, each returning day,\naround us hover while we pray;\nnew perils past, new sins forgiven,\nnew thoughts of God, new hopes of heaven.", "If on our daily course our mind\nbe set to hallow all we find,\nnew treasures still, of countless price,\nGod will provide for sacrifice.", "Old friends, old scenes, will lovelier be,\nas more of heaven in each we see;\nsome softening gleam of love and prayer\nshall dawn on every cross and care.", "The trivial round, the common task,\nwill furnish all we ought to ask:\nroom to deny ourselves; a road\nto bring us daily nearer God.", "Only, O Lord, in thy dear love,\nfit us for perfect rest above;\nand help us, this and every day,\nto live more nearly as we pray."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/10"},
  "24": {"firstLine": "The day thou gavest, Lord, is ended", "credit": "Author: John Ellerton, 1826-1893", "source": null, "stanzas": ["The day thou gavest, Lord, is ended,\nthe darkness falls at thy behest;\nto thee our morning hymns ascended,\nthy praise shall sanctify our rest.", "We thank thee that thy Church, unsleeping\nwhile earth rolls onward into light,\nthrough all the world her watch is keeping\nand rests not now by day or night.", "As o’er each continent and island\nthe dawn leads on another day,\nthe voice of prayer is never silent,\nnor dies the strain of praise away.", "So be it, Lord; thy throne shall never,\nlike earth’s proud empires, pass away:\nthy kingdom stands, and grows forever,\ntill all thy creatures own thy sway."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/24"},
  "37": {"firstLine": "O brightness of the immortal Father's face", "credit": "Translator: Edward W. Eddis, 1825-1905", "source": "Greek, 3rd cent. O Gracious Light (para.)", "stanzas": ["O brightness of the immortal Father's face,\nmost holy, heavenly, blest,\nLord Jesus Christ, in whom his truth and grace\nare visibly expressed:", "The sun is sinking now, and one by one\nthe lamps of evening shine;\nwe hymn the eternal Father, and the Son,\nand Holy Ghost divine.", "Worthy art thou at all times to receive\nour hallowed praises, Lord.\nO Son of God, be thou, in whom we live,\nthrough all the world adored."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/37"},
  "43": {"firstLine": "All praise to thee, my God, this night", "credit": "Author: Thomas Ken, 1637-1711", "source": null, "stanzas": ["All praise to thee, my God, this night,\nfor all the blessings of the light:\nkeep me, O keep me, King of kings,\nbeneath thine own almighty wings.", "Forgive me, Lord, for thy dear Son,\nthe ill that I this day have done;\nthat with the world, myself, and thee,\nI, ere I sleep, at peace may be.", "O may my soul on thee repose,\nand with sweet sleep mine eyelids close;\nsleep that shall me more vigorous make\nto serve my God when I awake.", "Praise God, from whom all blessings flow;\npraise him, all creatures here below;\npraise him above, ye heavenly host:\npraise Father, Son, and Holy Ghost."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/43"},
  "49": {"firstLine": "Come, let us with our Lord arise", "credit": "Author: Charles Wesley, 1707-1788", "source": null, "stanzas": ["Come, let us with our Lord arise,\nour Lord, who made both earth and skies,\nwho died to save the world he made\nand rose triumphant from the dead;\nhe rose, the prince of life and peace,\nand stamped the day for ever his.", "This is the day the Lord hath made\nthat all may see his love displayed,\nmay feel his resurrection's power\nand rise again to fall no more,\nin perfect righteousness renewed\nand filled with all the life of God.", "Then let us render him his own,\nwith solemn prayer approach the throne,\nwith meekness hear the gospel word,\nwith thanks his dying love record;\nour joyful hearts and voices raise\nand fill his courts with songs of praise."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/49"},
  "57": {"firstLine": "Lo! he comes, with clouds descending", "credit": "Author: Charles Wesley, 1707-1788", "source": null, "stanzas": ["Lo! he comes with clouds descending,\nonce for our salvation slain;\nthousand, thousand saints attending\nswell the triumph of his train:\nAlleluia! Alleluia! Alleluia!\nChrist the Lord returns to reign.", "Every eye shall now behold him,\nrobed in dreadful majesty;\nthose who set at nought and sold him,\npierced, and nailed him to the tree,\ndeeply wailing, deeply wailing, deeply wailing,\nshall the true Messiah see.", "Those dear tokens of his passion\nstill his dazzling body bears,\ncause of endless exultation\nto his ransomed worshipers;\nwith what rapture, with what rapture, with what rapture,\ngaze we on those glorious scars!", "Yea, amen! let all adore thee,\nhigh on thine eternal throne;\nSavior, take the power and glory;\nclaim the kingdom for thine own:\nAlleluia! Alleluia! Alleluia!\nThou shalt reign, and thou alone."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/57"},
  "66": {"firstLine": "Come, thou long-expected Jesus", "credit": "Author: Charles Wesley, 1707-1788", "source": null, "stanzas": ["Come, thou long-expected Jesus\nborn to set thy people free;\nfrom our fears and sins release us,\nlet us find our rest in thee.", "Israel's strength and consolation,\nhope of all the earth thou art:\ndear desire of every nation,\njoy of every longing heart.", "Born thy people to deliver,\nborn a child, and yet a king,\nborn to reign in us for ever,\nnow thy gracious kingdom bring.", "By thine own eternal Spirit\nrule in all our hearts alone;\nby thine all-sufficient merit,\nraise us to thy glorious throne."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/66"},
  "71": {"firstLine": "Hark! the glad sound! the Savior comes", "credit": "Author: Philip Doddridge, 1702-1751", "source": null, "stanzas": ["Hark, the glad sound! the Savior comes,\nthe Savior promised long:\nlet every heart prepare a throne,\nand every voice a song.", "He comes, the prisoners to release\nin Satan's bondage held;\nthe gates of brass before him burst,\nthe iron fetters yield.", "He comes, the broken heart to bind,\nthe bleeding soul to cure;\nand with the treasures of his grace\nto enrich the humble poor.", "Our glad hosannas, Prince of Peace,\nthy welcome shall proclaim;\nand heaven's eternal arches ring\nwith thy beloved Name."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/71"},
  "78": {"firstLine": "O little town of Bethlehem", "credit": "Author: Phillips Brooks, 1835-1893", "source": null, "stanzas": ["O little town of Bethlehem,\nhow still we see thee lie!\nAbove thy deep and dreamless sleep\nthe silent stars go by;\nyet in thy dark streets shineth\nthe everlasting Light;\nthe hopes and fears of all the years\nare met in thee tonight.", "For Christ is born of Mary;\nand gathered all above,\nwhile mortals sleep, the angels keep\ntheir watch of wondering love.\nO morning stars, together\nproclaim the holy birth!\nand praises sing to God the King,\nand peace to men on earth.", "How silently, how silently,\nthe wondrous Gift is given!\nSo God imparts to human hearts\nthe blessings of his heaven.\nNo ear may hear his coming,\nbut in this world of sin,\nwhere meek souls will receive him, still\nthe dear Christ enters in.", "Where children pure and happy\npray to the blessed Child,\nwhere misery cries out to thee,\nSon of the mother mild;\nwhere charity stand watching\nand faith holds wide the door,\nthe dark night wakes, the glory breaks,\nand Christmas comes once more.", "O holy Child of Bethlehem,\ndescend to us, we pray;\ncast out our sin and enter in,\nbe born in us today.\nWe hear the Christmas angels\nthe great glad tidings tell;\nO come to us, abide with us,\nour Lord Emmanuel!"], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/78"},
  "83": {"firstLine": "O come, all ye faithful", "credit": "Author: John Francis Wade, 1711-1786; Translator: Frederick Oakeley, 1802-1880", "source": "Other translators also", "stanzas": ["O come, all ye faithful,\njoyful and triumphant,\nO come ye, O come ye to Bethlehem;\ncome, and behold him,\nborn the King of angels;", "God from God,\nLight from Light eternal,\nlo! he abhors not the Virgin's womb;\nonly-begotten\nSon of the Father;", "Sing, choirs of angels,\nsing in exultation;\nsing, all ye citizens of heaven above;\nglory to God,\nglory in the highest;", "See how the shepherds,\nsummoned to his cradle,\nleaving their flocks, draw nigh to gaze;\nwe too will thither\nbend our joyful footsteps;", "Child, for us sinners\npoor and in the manger,\nwe would embrace thee, with love and awe;\nwho would not love thee,\nloving us so dearly?", "Yea, Lord, we greet thee,\nborn this happy morning;\nJesus, to thee be glory given;\nWord of the Father,\nnow in flesh appearing;"], "refrain": "O come, let us adore him,\nO come, let us adore him,\nO come, let us adore him,\nChrist the Lord.", "from": "https://hymnary.org/hymn/EH1982/83"},
  "94": {"firstLine": "While shepherds watched their flocks by night", "credit": "Author: Nahum Tate, 1652-1715", "source": null, "stanzas": ["While shepherds watched their flocks by night,\nall seated on the ground,\nthe angel of the Lord came down,\nand glory shone around.", "\"Fear not,\" said he, for mighty dread\nhad seized their troubled mind;\n\"Glad tidings of great joy I bring\nto you and all mankind.", "\"To you, in David's town, this day\nis born of David's line\na Savior, who is Christ the Lord;\nand this shall be the sign:", "\"The heavenly Babe you there shall find\nto human view displayed,\nall meanly wrapped in swathing bands,\nand in a manger laid.\"", "Thus spake the seraph, and forthwith\nappeared a shining throng\nof angels praising God, who thus\naddressed their joyful song:", "\"All glory be to God on high\nand on earth be peace;\ngood will henceforth from heaven to men\nbegin and never cease.\""], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/94"},
  "97": {"firstLine": "Dost thou in a manger lie", "credit": "Author: Jean Mauburn, 1460-1503; Translator: Elizabeth Rundle Charles, 1828-1896", "source": "Other translators also", "stanzas": ["Dost thou in a manger lie,\nwho hast all created,\nstretching infant hands on high,\nSavior, long awaited?\nIf a monarch, where thy state?\nWhere thy court on thee to wait?\nScepter, crown, and sphere?\nHere no regal pomp we see,\nnought but need and penury:\nwhy thus cradled here?", "\"For the world a love supreme\nbrought me to this stable;\nall creation to redeem\nI alone am able.\nBy this lowly birth of mine,\nsinner, riches shall be thine,\nmatchless gifts and free;\nwillingly this yoke I take,\nand this sacrifice I make,\nheaping joys for thee.\"", "Christ we praise with voices bold,\nlaud and honor raising;\nfor these mercies manifold\njoin the hosts in praising:\nFather, glory be to thee\nfor the wondrous charity\nof thy Son, our Lord.\nBetter witness to thy worth,\npurer praise than ours on earth.\nangels' songs afford."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/97"},
  "101": {"firstLine": "Away in a manger, no crib for his bed", "credit": "Traditional carol", "source": "Traditional carol", "stanzas": ["Away in a manger, no crib for his bed,\nthe little Lord Jesus laid down his sweet head.\nThe stars in the bright sky looked down where he lay,\nthe little Lord Jesus asleep on the hay.", "The cattle are lowing, the baby awakes,\nbut little Lord Jesus, no crying he makes.\nI love thee, Lord Jesus! Look down from the sky,\nand stay by my side until morning is nigh.", "Be near me, Lord Jesus; I ask thee to stay\nclose by me forever, and love me I pray.\nBless all the dear children in thy tender care,\nand fit us for heaven to live with thee there."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/101"},
  "109": {"firstLine": "The first Nowell the angel did say", "credit": "English carol, 18th cent.", "source": "English carol, 18th cent.", "stanzas": ["The first Nowell the angel did say\nwas to certain poor shepherds in fields as they lay;\nin fields where they lay, keeping their sheep,\non a cold winter's night that was so deep.", "They looked up and saw a star\nshining in the east beyond them far,\nand to the earth it gave great light,\nand so it continued both day and night.", "And by the light of that same star\nthree wise men came from country far;\nto seek for a king was their intent,\nand to follow the star wherever it went.", "This star drew nigh to the northwest,\no'er Bethlehem it took its rest,\nand there it did both stop and stay\nright over the place where Jesus lay.", "Then entered in those wise men three\nfull reverently upon their knee,\nand offered there in his presence\ntheir gold, and myrrh, and frankincense.", "Then let us all with one accord\nsing praises to our heavenly Lord;\nthat hath made Heaven and earth of nought,\nand with his blood our life hath bought."], "refrain": "Nowell, Nowell, Nowell, Nowell,\nborn is the King of Israel.", "from": "https://hymnary.org/hymn/EH1982/109"},
  "110": {"firstLine": "The snow lay on the ground", "credit": "Unknown source, 19th cent.", "source": "Unknown source, 19th cent.", "stanzas": ["The snow lay on the ground, the stars shone bright,\nwhen Christ our Lord was born on Christmas night.\nVenite adoremus Dominum.\nVenite adoremus Dominum.", "'Twas Mary, daughter pure of holy Anne,\nthat brought into this world the God made man.\nShe laid him in a stall at Bethlehem;\nthe ass and oxen shared the roof with them.", "Saint Joseph, too, was by to tend the child;\nto guard him, and protect his mother mild;\nthe angels hovered round, and sang this song,\nVenite adoremus Dominum.", "And thus that manger poor became a throne;\nfor he whom Mary bore was God the Son.\nO come, then, let us join the heavenly host;\nto praise the Father, Son, and Holy Ghost."], "refrain": "Venite adoremus Dominum.\nVenite adoremus Dominum.", "from": "https://hymnary.org/hymn/EH1982/110"},
  "111": {"firstLine": "Silent night, holy night", "credit": "Author: Joseph Mohr, 1792-1848; Translator: John Freeman Young, 1820-1885", "source": null, "stanzas": ["Silent night, holy night,\nall is calm, all is bright\nround yon virgin mother and child.\nHoly infant, so tender and mild,\nsleep in heavenly peace.\nSleep in heavenly peace.", "Silent night, holy night,\nshepherds quake at the sight,\nglories stream from heaven afar,\nheavenly hosts sing alleluia;\nChrist, the Savior, is born!\nChrist, the Savior, is born!", "Silent night, holy night,\nSon of God, love's pure light\nradiant beams from thy holy face,\nwith the dawn of redeeming grace,\nJesus, Lord at thy birth.\nJesus, Lord at thy birth."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/111"},
  "112": {"firstLine": "In the bleak midwinter", "credit": "Author: Christina Rossetti, 1830-1894", "source": null, "stanzas": ["In the bleak midwinter, frosty wind made moan,\nearth stood hard as iron, water like a stone;\nsnow had fallen, snow on snow, snow on snow,\nin the bleak midwinter, long ago.", "Our God, heaven cannot hold him, nor earth sustain;\nheaven and earth shall flee away when he comes to reign:\nin the bleak midwinter a stable place sufficed\nthe Lord God incarnate, Jesus Christ.", "Angels and archangels may have gathered there,\ncherubim and seraphim thronged the air;\nbut his mother only, in her maiden bliss,\nworshiped the beloved with a kiss.", "What can I give him, poor as I am?\nIf I were a shepherd, I would bring a lamb;\nif I were a wise man, I would do my part;\nyet what I can I give him—give my heart."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/112"},
  "115": {"firstLine": "What child is this, who, laid to rest", "credit": "Author: William Chatterton Dix, 1837-1898", "source": null, "stanzas": ["What child is this, who, laid to rest,\non Mary's lap is sleeping?\nWhom angels greet with anthems sweet,\nwhile shepherds watch are keeping?", "Why lies he in such mean estate\nwhere ox and ass are feeding?\nGood Christian, fear: for sinners here\nthe silent Word is pleading.", "So bring him incense, gold, and myrrh,\ncome, peasant, king, to own him;\nthe King of kings salvation brings,\nlet loving hearts enthrone him."], "refrain": "This, this is Christ the King,\nwhom shepherds guard and angels sing;\nhaste, haste to bring him laud,\nthe babe, the son of Mary.", "from": "https://hymnary.org/hymn/EH1982/115"},
  "119": {"firstLine": "As with gladness men of old", "credit": "Author: William Chatterton Dix, 1837-1898", "source": null, "stanzas": ["As with gladness men of old\ndid the guiding star behold;\nas with joy they hailed its light,\nleading onward, beaming bright;\nso, most gracious Lord, may we\nevermore be led to thee.", "As with joyful steps they sped\nto that lowly manger-bed;\nthere to bend the knee before\nhim whom heaven and earth adore;\nso may we with willing feet\never seek the mercy-seat.", "As they offered gifts most rare\nat that manger rude and bare;\nso may we with holy joy,\npure and free from sin's alloy,\nall our costliest treasures bring,\nChrist! to thee, our heavenly King.", "Holy Jesus! every day\nkeep us in the narrow way;\nand, when earthly things are past,\nbring our ransomed souls at last\nwhere they need no star to guide,\nwhere no clouds thy glory hide.", "In the heavenly country bright,\nneed they no created light;\nthou its light, its joy, its crown,\nthou its sun which goes not down;\nthere for ever may we sing\nalleluias to our King."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/119"},
  "140": {"firstLine": "Wilt thou forgive that sin, where I begun", "credit": "Author: John Donne, 1573-1631", "source": null, "stanzas": ["Wilt thou forgive that sin, where I begun,\nwhich is my sin, though it were done before?\nWilt thou forgive those sins through which I run,\nand do run still, though still I do deplore?\nWhen thou hast done, thou hast not done,\nfor I have more.", "Wilt thou forgive that sin, by which I won\nothers to sin, and made my sin their door?\nWilt thou forgive that sin which I did shun\na year or two, but wallowed in a score?\nWhen thou hast done, thou hast not done,\nfor I have more.", "I have a sin of fear that when I've spun\nmy last thread, I shall perish on the shore;\nswear by thyself, that at my death thy Son\nshall shine as he shines now, and heretofore.\nAnd having done that, thou hast done,\nI fear no more."], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/140"},
  "142": {"firstLine": "Lord, who throughout these forty days", "credit": "Author: Claudia Frances Hernaman, 1838-1898", "source": null, "stanzas": ["Lord, who throughout these forty days\nfor us didst fast and pray,\nteach us with thee to mourn our sins,\nand close by thee to stay.", "As thou with Satan didst contend\nand didst the victory win,\nO give us strength in thee to fight,\nin thee to conquer sin.", "As thou didst hunger bear and thirst,\nso teach us, gracious Lord,\nto die to self, and chiefly live\nby thy most holy word.", "And through these days of penitence,\nand through thy Passiontide,\nyea, evermore, in life and death,\nJesus! with us abide.", "Abide with us, that so, this life\nof suffering overpast,\nan Easter of unending joy\nwe may attain at last!"], "refrain": null, "from": "https://hymnary.org/hymn/EH1982/142"},
};

/** hymnKey (lib/hymnsCatalogue) -> the number whose text it sings. */
const BY_KEY: Record<string, string> = {"6-7": "6", "10": "10", "24": "24", "37": "37", "43": "43", "49": "49", "57-58": "57", "66": "66", "71-72": "71", "78-79": "78", "83": "83", "94-95": "94", "97": "97", "101": "101", "109": "109", "110": "110", "111": "111", "112": "112", "115": "115", "119": "119", "140-141": "140", "142": "142"};

/** The public-domain words for a recording, or null (then show none). */
export function hymnTextFor(key: string | null | undefined): HymnText | null {
  if (!key) return null;
  const n = BY_KEY[key];
  return n ? TEXTS[n] ?? null : null;
}
